cd /tmp/sv-29e3a32d2c8e4182b536e5eacf990624/symbols

# Check what symbols are available - try dynamic symbols
nm -D libmonosgen-2.0.so 2>/dev/null | wc -l
# Get symbols near our addresses
nm -D libmonosgen-2.0.so 2>/dev/null | sort | awk '
/^[0-9a-f]/ {
  addr = strtonum("0x" $1)
  name = $3
  syms[addr] = name
  addrs[++n] = addr
}
END {
  targets[1] = 0x222098
  targets[2] = 0x222234
  targets[3] = 0x19bac0
  targets[4] = 0x19bc14
  targets[5] = 0x008f14
  targets[6] = 0x003b20
  targets[7] = 0x012a48
  for (t = 1; t <= 4; t++) {
    best = 0
    for (i = 1; i <= n; i++) {
      if (addrs[i] <= targets[t] && addrs[i] > best) {
        best = addrs[i]
        bestname = syms[addrs[i]]
      }
    }
    printf "0x%x -> %s+0x%x\n", targets[t], bestname, targets[t] - best
  }
}' 2>/dev/null

