arguments.command:
cd /tmp/sv-29e3a32d2c8e4182b536e5eacf990624/symbols

# Check sections
readelf -S libmonosgen-2.0.so 2>/dev/null | grep -E "symtab|debug|dynsym"

# Try looking for closer symbols using all available dynamic symbols
# Sort by address and find surrounding symbols for each target
nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort > /tmp/mono_syms.txt

for addr in 222098 222234 19bac0 19bc14; do
  echo "--- 0x$addr ---"
  # find the symbol just before and just after
  awk -v target="0x$addr" '
  BEGIN { tgt = strtonum(target) }
  /^[0-9a-f]/ {
    a = strtonum("0x" $1)
    if (a <= tgt) { prev_addr = a; prev_name = $3 }
    if (a > tgt && !found) { next_addr = a; next_name = $3; found = 1 }
  }
  END {
    printf "  %s+0x%x (next: %s at +0x%x)\n", prev_name, tgt - prev_addr, next_name, next_addr - tgt
  }' /tmp/mono_syms.txt
done

